const entrada = $input.first().json;
const body = entrada.body ?? entrada;
const limpio = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, max);
const escapar = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const nombre = limpio(body.nombre, 60);
const apellido = limpio(body.apellido, 60);
const email = limpio(body.email, 254).toLowerCase();
const mensaje = limpio(body.mensaje, 500);
const origen = limpio(body.origen || 'web-form', 30);
const acepta = limpio(body.consentimiento, 10).toLowerCase() === 'si';

// Dominios de correo desechable. Lista corta y orientativa: no caza todos. Para ampliarla, añade dominios en minúsculas.
const DESECHABLES = new Set([
  "10mail.org", "10minemail.com", "10minutemail.com", "10minutemail.net", "10minutemail.org", "20minutemail.com",
  "20minutemail.it", "33mail.com", "abyssmail.com", "anonbox.net", "anonymbox.com", "armyspy.com",
  "bccto.me", "burnermail.io", "cmail.net", "courriel.fr.nf", "crazymailing.com", "cuvox.de",
  "dayrep.com", "discard.email", "discardmail.com", "discardmail.de", "disposablemail.com", "dispostable.com",
  "dropmail.me", "easytrashmail.com", "einrot.com", "email-fake.com", "emailfake.com", "emailondeck.com",
  "emltmp.com", "ephemail.net", "fakeinbox.com", "fakemail.net", "fakemailgenerator.com", "fexbox.org",
  "fexpost.com", "fleckens.hu", "getairmail.com", "getnada.com", "grr.la", "guerrillamail.biz",
  "guerrillamail.com", "guerrillamail.de", "guerrillamail.info", "guerrillamail.net", "guerrillamail.org", "guerrillamailblock.com",
  "gustr.com", "harakirimail.com", "inboxbear.com", "inboxkitten.com", "jetable.fr.nf", "jourrapide.com",
  "linshiyouxiang.net", "lroid.com", "mail-temporaire.fr", "mailcatch.com", "maildrop.cc", "mailforspam.com",
  "mailmoat.com", "mailnesia.com", "mailnull.com", "mailpoof.com", "mailsac.com", "mailtemp.info",
  "meltmail.com", "mega.zik.dj", "minuteinbox.com", "mintemail.com", "moakt.com", "mohmal.com",
  "mohmal.in", "mohmal.tech", "moncourrier.fr.nf", "monemail.fr.nf", "monmail.fr.nf", "mt2015.com",
  "mvrht.com", "my10minutemail.com", "mytemp.email", "mytrashmail.com", "nada.email", "nada.ltd",
  "nospam.ze.tc", "nowmymail.com", "objectmail.com", "owlpic.com", "pjjkp.com", "pokemail.net",
  "proxymail.eu", "rcpt.at", "rhyta.com", "rmqkr.net", "safetymail.info", "selfdestructingmail.com",
  "sendspamhere.com", "sharklasers.com", "sneakemail.com", "snkmail.com", "sofort-mail.de", "sogetthis.com",
  "soodonims.com", "spam4.me", "spambog.com", "spambog.de", "spambog.ru", "spambox.us",
  "spamex.com", "spamfree24.org", "spamgourmet.com", "spamgourmet.net", "spamgourmet.org", "spamhole.com",
  "spaml.com", "speed.1s.fr", "superrito.com", "supergreatmail.com", "suremail.info", "teleworm.us",
  "temp-mail.io", "temp-mail.org", "temp-mail.ru", "tempail.com", "tempemail.net", "tempinbox.com",
  "tempmail.com", "tempmail.dev", "tempmail.email", "tempmail.net", "tempmailaddress.com", "tempmailer.com",
  "tempmailer.de", "tempmailo.com", "tempr.email", "tempsky.com", "temporary-mail.net", "thankyou2010.com",
  "thisisnotmyrealemail.com", "throwam.com", "throwawaymail.com", "tmail.ws", "tmailinator.com", "tmpeml.com",
  "tmpmail.net", "tmpmail.org", "trash-mail.com", "trash-mail.de", "trashmail.com", "trashmail.de",
  "trashmail.io", "trashmail.me", "trashmail.net", "trbvm.com", "trillianpro.com", "tyldd.com",
  "uroid.com", "veryrealemail.com", "vomoto.com", "wegwerfmail.de", "wegwerfmail.net", "wegwerfmail.org",
  "wh4f.org", "willhackforfood.biz", "yopmail.com", "yopmail.fr", "yopmail.net", "zehnminuten.de",
  "zoemail.org", "mailinator.com", "mailinator.net", "mailinator.org", "mailinator2.com",
]);
// Prueba el dominio y sus partes (a.b.mailinator.com -> b.mailinator.com -> mailinator.com).
const esDesechable = (dominio) => { const p = dominio.split('.'); return p.some((_, i) => DESECHABLES.has(p.slice(i).join('.'))); };

const errores = [];
if (!nombre) errores.push('El nombre es obligatorio.');
if (!/^[^\s@<>,;"']+@[^\s@<>,;"']+\.[^\s@<>,;"']{2,}$/.test(email)) errores.push('El email no es válido.');
else if (esDesechable(email.split('@')[1])) errores.push('El email parece temporal o desechable. Usa uno que consultes habitualmente.');
if (!acepta) errores.push('Debes aceptar la política de privacidad.');
if (limpio(body.web, 100)) errores.push('Solicitud rechazada.');

const mensajeCorto = mensaje.length > 80 ? mensaje.slice(0, 80) + '...' : mensaje;
const fecha = new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
const id = 'LEAD-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 5);

return [{ json: {
  valido: errores.length === 0, errores, id, fecha, origen,
  consentimiento: acepta ? fecha : '',
  nombre, apellido, email, mensaje,
  nombreH: escapar(nombre), apellidoH: escapar(apellido), emailH: escapar(email), mensajeCortoH: escapar(mensajeCorto),
} }];

